f8o/5Z/yT/mn/FP+L8r/AzeAs3AAyAAA
DARK_APP_PAYLOAD

# the theme
cp -r "$T/theme/usr/." /usr/
# the Themes app + the Amber theme (so you can always switch back)
python3 -c 'import PyQt5' 2>/dev/null || { echo "STATUS:Installing what the Themes app needs..."; apt-get install -y -q python3-pyqt5 >/dev/null 2>&1; }
cp -r "$T/app/usr/." /usr/
chmod 755 /usr/share/mikeos-amber/bin/amber-themes
chmod -R a+rX /usr/share/mikeos-amber/themes /usr/share/lxqt/themes/dark-amber /usr/share/themes/Dark-Amber /usr/share/wallpapers/MikeOS-Dark-Amber 2>/dev/null

# full desktop (KDE): a dark taskbar style, made from the standard one
if [ -d /usr/share/plasma/desktoptheme/default ]; then
    D=/usr/share/plasma/desktoptheme/mikeos-dark-amber
    rm -rf "$D"; cp -r /usr/share/plasma/desktoptheme/default "$D"
    rm -f "$D/metadata.desktop"
    cat > "$D/metadata.json" <<'META'
{ "KPlugin": { "Id": "mikeos-dark-amber", "Name": "Dark Amber", "Description": "Mike OS Dark Amber taskbar",
  "Authors": [ { "Name": "Mike OS" } ], "License": "LGPL", "Version": "1.0" },
  "X-Plasma-API": "5.0" }
META
    cp /usr/share/mikeos-amber/themes/dark-amber/plasma-colors "$D/colors"
fi
command -v update-desktop-database >/dev/null && update-desktop-database -q /usr/share/applications || true
rm -rf "$T"

# dark mode text fix: apps with their own light design keep their light Amber colours
echo "STATUS:Fixing app text for dark mode..."
python3 - <<'DARK_FIX_PY'
import os, re
FILES = ["/usr/share/mikeos-amber/apps/store.py", "/usr/share/mikeos-amber/apps/themes.py",
         "/usr/share/mikeos-amber/apps/welcome.py", "/usr/share/mikeos-amber/apps/wifi.py",
         "/usr/share/mikeos-amber/bin/amber-update-check", "/opt/mike-paint/mikepaint.py",
         "/opt/mike-screensaver/screensaver.py", "/opt/amber-antivirus/amber_antivirus.py"]
SNIP = '''{i}# Dark themes: this window has its own light Amber design, so keep the light Amber colours for it
{i}# (otherwise the dark theme's white text lands on its light backgrounds).
{i}from PyQt5.QtGui import QColor as _AmberC, QPalette as _AmberP
{i}if app.palette().color(_AmberP.Window).lightness() < 128:
{i}    _pal = _AmberP()
{i}    for _role, _col in ((_AmberP.Window, "#cfa5e8"), (_AmberP.WindowText, "#1c0a2e"), (_AmberP.Base, "#fbf7ff"),
{i}                        (_AmberP.AlternateBase, "#f3e8ff"), (_AmberP.Text, "#1c0a2e"), (_AmberP.Button, "#e6d2f4"),
{i}                        (_AmberP.ButtonText, "#1c0a2e"), (_AmberP.Highlight, "#f08a00"),
{i}                        (_AmberP.HighlightedText, "#1a0f00"), (_AmberP.Link, "#1560d8"),
{i}                        (_AmberP.LinkVisited, "#7a12c4"), (_AmberP.ToolTipBase, "#fbf7ff"),
{i}                        (_AmberP.ToolTipText, "#1c0a2e"), (_AmberP.PlaceholderText, "#8a7a9a"),
{i}                        (_AmberP.Light, "#ffffff"), (_AmberP.Midlight, "#e6d2f4"), (_AmberP.Mid, "#a98bc0"),
{i}                        (_AmberP.Dark, "#7d5c98"), (_AmberP.Shadow, "#3d2a52")):
{i}        _pal.setColor(_role, _AmberC(_col))
{i}    for _role in (_AmberP.WindowText, _AmberP.Text, _AmberP.ButtonText):
{i}        _pal.setColor(_AmberP.Disabled, _role, _AmberC("#8a7a9a"))
{i}    app.setPalette(_pal)
'''
for f in FILES:
    if not os.path.exists(f):
        continue                                  # that app isn't installed
    s = open(f).read()
    if "_AmberP" in s:
        pass
        continue
    m = re.search(r"^( *)app = QApplication\(sys\.argv\)\n", s, re.M)
    if not m:
        pass
        continue
    s = s[:m.end()] + SNIP.format(i=m.group(1)) + s[m.end():]
    mode = os.stat(f).st_mode
    with open(f + ".new", "w") as out:
        out.write(s)
    os.chmod(f + ".new", mode)
    os.replace(f + ".new", f)
DARK_FIX_PY
mkdir -p /var/lib/mikeos-amber && touch /var/lib/mikeos-amber/dark-text-fix-1

# open the Themes app so Dark Amber can be switched on
mapfile -t envs < <(desktop_env)
if [ ${#envs[@]} -gt 0 ]; then
    sudo -u "$USER_NAME" env HOME="$USER_HOME" "${envs[@]}" setsid python3 /usr/share/mikeos-amber/apps/themes.py >/dev/null 2>&1 < /dev/null &
fi
echo "Dark Amber installed - turn it on in the Themes app (start menu > Preferences > Themes)."
